/* Original practice questions based on the instructor's Chapter_9 and Chapter_10 decks.
   Slide references use physical deck positions, reviewed 20 October 2026.
   Numerical models are classroom assumptions, not observations of a real plant.
   Correct answers are stored first; the session engine shuffles all answer choices. */
(function () {
  "use strict";
  const questions = [];
  let chapter, section, topic;
  const group = (c, s, t) => { chapter = c; section = s; topic = t; };
  const q = (id, slide, prompt, correct, distractors, explanation, media = null) =>
    questions.push({ id: `es${chapter}-${id}`, chapter, section, topic, slide, prompt,
      options: [correct, ...distractors], answer: 0, explanation, media });

  group(9, "Science", "Fuels and formation");
  q("coal-origin",7,"Which material is the main starting point for coal formation?","Plant remains accumulated in ancient wetlands",["Marine shells dissolved in seawater","Uranium trapped in volcanic rock","Recently fallen leaves compressed for a few weeks"],"Coal forms from accumulated vegetation altered by burial, heat and pressure over geological time.");
  q("petroleum-origin",12,"The petroleum-formation sequence begins mainly with which material?","Organic remains of ancient aquatic organisms",["Mostly the remains of large land dinosaurs","Coal transported into a modern refinery","Fresh sediment converted to oil within a season"],"Buried aquatic organic matter can become petroleum under suitable geological conditions. The process takes far longer than human consumption.");
  q("nonrenewable",29,"Why do the slides classify fossil fuels as nonrenewable?","Their formation is much slower than their use on human timescales",["No additional deposits can ever be discovered","Burning them creates no useful energy","They exist only in one country"],"Renewability concerns replenishment relative to use. Discovering a deposit does not make the underlying resource renew quickly.");
  q("stored-energy",29,"What kind of energy do coal, oil and natural gas store before combustion?","Chemical energy",["Electrical current","The kinetic energy of a turbine","The energy of a controlled nuclear chain reaction"],"Combustion releases chemical energy. A power plant then converts some of that energy into useful electricity.");
  q("coal-rank",8,"As coal generally progresses from lignite toward anthracite, which property tends to increase?","Carbon concentration and energy content per unit mass",["Moisture content","The rate at which new coal grows","The number of living plant cells"],"Increasing coal rank generally means greater carbon concentration and energy content, with less moisture. Coal grades are not interchangeable.");
  q("refinery",13,"What allows an oil refinery's distillation column to separate crude oil into fractions?","Different boiling ranges",["Different levels of radioactivity","Identical boiling points","The electrical charge of whole fuel molecules"],"Heating and cooling separate fractions with different boiling ranges. Refining supplies several products, not just electricity-generation fuel.");
  q("oil-products",13,"Why is an electricity-only comparison an incomplete description of oil use?","Oil also supplies transport fuels and industrial feedstocks",["Oil cannot be converted to heat","All oil is used in nuclear reactors","Refineries produce only electricity"],"Refining produces fuels and other materials. Define the useful service before comparing energy pathways.");
  q("methane",17,"Which molecule is the principal component of natural gas?","Methane",["Carbon dioxide","Uranium hexafluoride","Ethanol"],"Natural gas consists predominantly of methane. Other hydrocarbons can accompany it.");
  q("hydrocarbons",17,"What do methane, ethane, propane and butane have in common?","They are hydrocarbons made of carbon and hydrogen",["They all contain uranium","They are all renewable fuels","They contain only hydrogen"],"The displayed molecules contain carbon and hydrogen. Their different molecular sizes help explain their different properties.");
  q("gas-trap",20,"What is the role of an impermeable cap rock above a petroleum reservoir?","It can impede upward migration and help trap fluids",["It creates electricity","It converts oil directly into coal","It guarantees the deposit contains no water"],"A trap combines suitable reservoir geometry and a sealing layer. The schematic is a geological example, not a universal arrangement of all deposits.");
  q("gas-coal",20,"Natural gas in the chapter's geological illustration occurs in which settings?","With oil and in association with coal beds",["Only above sea level","Only inside nuclear fuel rods","Only in the atmosphere"],"Gas may occur with petroleum, with coal beds, or in other formations. A particular drawing does not describe every reservoir.");

  group(9, "Science", "Energy conversion");
  q("carrier",1,"In the light-switch example, electricity is best described as what?","An energy carrier delivered to the bulb",["A primary fossil fuel","A substance created by the bulb","A renewable resource in every case"],"Electricity carries energy from a source to a device. Its environmental consequences depend partly on how that electricity was generated.");
  q("bulb",1,"A lit bulb converts electrical energy mainly into which outputs?","Light and heat",["New fossil fuel","Only sound","Uranium and neutrons"],"Light is the desired service, while heat is also an energy output. Energy accounting includes both.");
  q("steam-sequence",4,"Which sequence matches the steam power plant?","Heat produces steam; steam turns a turbine; the turbine drives a generator",["Steam produces electricity in the condenser before reaching a turbine","The generator heats the boiler; the boiler supplies mechanical rotation directly","Fuel supplies electric current directly to the transmission line"],"The thermal pathway links heat, mechanical rotation and electrical energy. Different components perform different jobs.");
  q("generator",5,"What is the generator's main conversion in the power-plant diagram?","Mechanical energy to electrical energy",["Chemical energy directly to electrical energy without motion","Electrical energy to mechanical rotation, as its main generating role","Heat directly to electricity without electromagnetic induction"],"The turbine supplies rotation. Electromagnetic induction in the generator converts that mechanical input into electrical output.");
  q("condenser",3,"Why does a steam-cycle plant include a condenser?","To reject heat and return steam to liquid water",["To create fuel from waste heat","To eliminate all heat losses","To absorb all carbon dioxide"],"Condensation rejects heat and allows the working water to circulate again. Cooling is part of the energy and environmental accounting.");
  q("efficiency35",28,"A classroom plant receives 100 energy units at 35% efficiency. How much becomes electricity?","35 units",["65 units","100 units","135 units"],"Useful electricity = input × efficiency = 100 × 0.35 = 35 units. The other 65 units leave mainly as heat.");
  q("heat65",28,"In the same 100-unit, 35%-efficient plant, what happens to the other 65 units?","They leave mainly as heat",["They disappear","They become an additional 65 units of electricity","They are automatically recycled without losses"],"The energy is conserved. Conversion efficiency describes how much becomes the desired output, not how much energy survives.");
  q("input200",28,"Using the slide's 35% classroom efficiency, 200 input units yield how much electricity?","70 units",["35 units","130 units","235 units"],"200 × 0.35 = 70 electricity units, leaving 130 units mainly as heat.");
  q("efficiency-boundary",28,"Which conclusion is justified by a higher conversion efficiency alone?","Less input is needed for the same useful output",["Every environmental impact must fall by the same percentage","The fuel has become renewable","Waste and cooling are no longer relevant"],"Efficiency improves the input-to-output relationship. Environmental effects still depend on extraction, fuel composition, location and waste management.");
  q("mix-history",27,"How should the electricity-mix charts in the presentation be used?","As historical comparisons with the dates and rounding caveats shown",["As exact current shares for every country","As measurements of all energy use, including every transport fuel","As proof that one mix has no environmental impacts"],"These charts show historical electricity generation, not today's total energy system. The printed totals and unspecified Brazil year require caution.");

  group(9, "Science", "Nuclear mechanisms");
  q("fission",23,"What happens during nuclear fission?","A heavy nucleus splits, releasing energy and neutrons",["Two light nuclei always combine","Coal molecules split into gasoline","Electric current creates fresh uranium"],"Fission of a suitable heavy nucleus releases energy and neutrons that can sustain further fission.");
  q("fusion",23,"Which description matches fusion?","Light nuclei combine into a heavier nucleus",["A heavy nucleus splits into smaller nuclei","A turbine spins inside a generator","Oil separates into boiling-range fractions"],"Fusion combines light nuclei. It differs fundamentally from the fission process used in the reactor example.");
  q("uranium235",23,"Which isotope is identified in the fission example?","Uranium-235",["Hydrogen-1","Helium-3","Carbon-12"],"The example shows neutron-induced fission of uranium-235. Keep the isotope name distinct from the name of the element alone.");
  q("nuclear-heat",22,"What replaces fuel combustion as the source of heat in the illustrated nuclear plant?","Controlled nuclear fission",["The condenser","Direct photovoltaic conversion","Coal washing"],"Fission supplies heat; the steam turbine and generator still perform mechanical and electrical conversion.");
  q("nuclear-circuits",21,"Why distinguish the separate water circuits in the illustrated nuclear plant?","They transfer heat while keeping different fluids separated",["All water must mix in the reactor","The cooling circuit creates uranium","Separate circuits remove the need for cooling"],"The reconstructed figure represents separate circuits that exchange heat without mixing. Reactor designs differ.");
  q("shutdown-heat",41,"Why can a reactor still require cooling after the chain reaction stops?","Radioactive products continue releasing decay heat",["The turbine creates unlimited heat from nothing","All fuel immediately becomes chemically flammable","A shutdown always increases the fission rate"],"Stopping the chain reaction does not instantly remove decay heat. Heat removal remains a safety responsibility.");
  q("chain-neutrons",23,"What allows one fission event to trigger further fission in a chain reaction?","Neutrons released by the event can interact with other suitable nuclei",["The generator creates new uranium with every turn","The condenser converts steam into neutrons","Every nuclear fragment immediately becomes coal"],"The released neutrons link successive events. A reactor regulates the chain reaction while removing heat.");
  q("containment",41,"What is containment intended to help limit in a nuclear accident?","The release of radioactive material to the surroundings",["The need to produce any useful electricity","All heat transfer through every circuit","The amount of daylight reaching the plant"],"Containment is a protective barrier. Its effectiveness and the accident sequence matter, alongside cooling and other safety functions.");
  q("gas-renewable",29,"Does a natural-gas deposit become renewable because it contains less carbon per unit of fuel than coal?","No; renewability depends on replenishment timescale",["Yes; any difference in composition makes a resource renewable","Yes; all gases replenish instantly","No; because natural gas contains no chemical energy"],"Resource renewal and fuel composition are different properties. Natural gas forms over geological time and is nonrenewable on human timescales.");

  group(9, "Issues", "Extraction and pollution");
  q("full-cycle",34,"Which boundary is most appropriate when comparing coal and nuclear electricity?","Extraction, processing, operation and waste management",["Only the visible smokestack","Only electricity at the outlet","Only the purchase price of fuel"],"A complete pathway includes upstream and downstream burdens. A narrow boundary can hide mining, water and waste impacts.");
  q("mountaintop",35,"Which effect directly follows from valley fills in mountaintop-removal mining?","Burial of headwater streams",["Restoration of the original mountain shape","Removal of all water pollution","Creation of a renewable coal supply"],"Rock and spoil can fill valleys and bury streams, altering drainage and habitats beyond the extraction pit.");
  q("satellite",36,"What can the paired 1987 and 2011 satellite images directly support?","A comparison of visible disturbed land in the same region",["An exact measurement of every resident's health","Proof of the chemical concentration in every stream","A forecast of all future mining"],"Imagery documents spatial change. Water chemistry and health outcomes require additional measurements.");
  q("sludge-ash",37,"Which pairing correctly distinguishes two coal wastes?","Washing produces sludge; combustion produces fly ash",["Washing produces uranium; combustion produces methane reservoirs","Washing produces fly ash; combustion produces peat","Both are forms of unburned crude oil"],"Coal processing and coal combustion create different waste streams, each requiring suitable containment and monitoring.");
  q("leaching",37,"Can coal-waste contaminants reach water without a dramatic pond failure?","Yes, metals can leach from stored waste",["No, only explosions release contaminants","No, a pond always neutralizes metals","Yes, but only if nuclear fuel is present"],"Routine leakage and leaching can matter as well as large failures. Visible disaster is not the only exposure pathway.");
  q("spill-livelihood",38,"Why does an oil-spill assessment include fishing and tourism?","Contamination can damage livelihoods as well as wildlife",["Those activities determine the oil's boiling point","Income loss proves wildlife cannot be affected","Only economic losses count as environmental effects"],"The presentation links habitat and wildlife damage to human well-being, including work and income.");
  q("spill-visible",38,"An oiled shoreline looks clean after treatment. What can you conclude?","Further evidence is needed to assess ecological recovery",["All contamination has disappeared","Every food web has recovered","Long-term monitoring is no longer useful"],"Oil or its effects can persist in sediments and organisms after surface oil is no longer visible.");
  q("oil-sands",39,"Which landscape change is central to the oil-sands example?","Removal of boreal forest and wetlands",["Instant creation of mature peatlands","No surface disturbance","Replacement of all fuel use with solar energy"],"Surface extraction removes overlying ecosystems. Later revegetation does not automatically restore their original functions.");
  q("fracking-stages",40,"At which stages can water risks arise in the hydraulic-fracturing water cycle?","Acquisition, mixing, injection, recovery and disposal",["Only deep underground","Only after all wells close","Only during electricity generation"],"The risk framework follows the whole water cycle, including surface handling and wastewater management.");
  q("withdrawal",40,"In a water-stressed area, which concern occurs before a fracturing fluid is injected?","Competition for water withdrawn for operations",["Decay heat from uranium","Fish passage through a turbine","The boiling point of gasoline"],"Water acquisition can compete with other users and ecosystem needs. Risks begin before injection.");
  q("methane-loss",43,"Which upstream concern is particularly important in the natural-gas pathway?","Methane leakage during production and transport",["Spent uranium fuel","Coal fly ash from every pipeline","Ocean tides reversing direction"],"A system-level assessment includes leakage as well as emissions at the point of combustion.");
  q("wastewater-quakes",43,"What distinction matters when discussing induced earthquakes in the slides?","Deep wastewater disposal is a distinct operation from hydraulic fracturing",["Every earthquake near a well has the same cause","Wastewater disposal and coal burning are identical","Geology never affects the risk"],"The extraction table explicitly distinguishes disposal-induced seismicity from fracturing. Site conditions and operational details matter.");
  q("uranium-tailings",41,"Why include uranium mining in a nuclear-energy assessment?","Mine residues can expose workers and communities to radioactive materials",["Uranium mining creates no waste","Mining is unrelated to reactor fuel","All residues become safe immediately"],"The fuel cycle begins before the reactor. Tailings and contaminated sites can require long-term management.");
  q("spent-fuel",41,"Which set of responsibilities matches spent nuclear fuel?","Cooling, shielding, secure storage and long-term isolation",["Only repainting its container","Dilution into ordinary surface water","Combustion in a coal boiler"],"Spent fuel can be highly radioactive and continue producing heat. Multiple protection functions remain necessary.");
  q("fukushima",42,"Which sequence is emphasized in the Fukushima example?","An earthquake and tsunami disabled power and cooling",["An oil tanker struck a refinery","Coal ash blocked a hydroelectric dam","A solar panel overloaded a wind turbine"],"The example highlights combined external hazards and loss of cooling. It should not be treated as identical to other nuclear accidents.");
  q("accidents-differ",42,"Why compare the three nuclear accidents separately?","Their initiating events, designs and containment outcomes differed",["They used identical reactors and had identical releases","Only their dates differed","Every accident has the same probability at every plant"],"A useful comparison follows failure mechanisms and consequences instead of treating all nuclear accidents as interchangeable.");
  q("peak-model",31,"What should a student say about the peak-oil curves shown in the deck?","They are historical model forecasts that depend on assumptions",["They are current measurements of future production","They prove the exact date oil will disappear","They have no assumptions about recoverable resources"],"Changing assumed recoverable oil changes the projected peak. The slide explicitly warns that these are historical forecasts.");
  q("consumption-chart",30,"The redrawn 1998–2014 energy graph uses approximate readings. Which use is most defensible?","Discussing broad historical patterns while retaining the approximation warning",["Reporting every plotted value as exact raw measurements","Calling it a forecast for the next decade","Inferring individual plant efficiency from its curves"],"Approximate reconstruction supports broad comparison, not invented numerical precision.");
  q("equal-impact",44,"A table lists a burden for each fuel. Does that mean the burdens have equal magnitude?","No; magnitudes and probabilities require separate evidence",["Yes; one table row always equals one unit of damage","Yes; every accident has identical severity","No; therefore no comparison is possible"],"An inventory identifies what to investigate. It does not establish equal exposure, impact or risk.");
  q("waste-heat",44,"Which operational burden can fossil-fuel and nuclear thermal plants share?","Cooling demand and rejected heat",["Identical fuel-mining wastes","Identical carbon dioxide emissions at the reactor","The same accident probability"],"They use different primary energy processes but can both require heat rejection. Shared mechanisms do not imply identical overall impacts.");

  group(9, "Solutions", "Safeguards and decisions");
  q("prevention",46,"Which action primarily prevents an oil release rather than cleaning it up?","Maintaining equipment and verifying well integrity",["Skimming an existing slick","Cleaning an already oiled bird","Sampling contaminated sediment after a spill"],"Prevention acts before oil escapes. Response and monitoring remain necessary because prevention is not a guarantee.");
  q("boom",48,"A surface slick approaches a sensitive shoreline. Which tool mainly helps contain it?","A boom",["A chemical dispersant acting as a physical barrier","A water-sampling bottle","A long-term wildlife survey"],"Booms can limit the spread of surface oil or protect sensitive areas when conditions permit.");
  q("skimmer",48,"Which tool is intended to collect accessible surface oil?","A skimmer",["A dispersant that only breaks the slick into droplets","A monitoring station measuring contamination","A boom that redirects oil without collecting it"],"Skimmers physically recover accessible oil. Performance depends on conditions such as waves and oil properties.");
  q("dispersants",47,"What is the key caution about chemical dispersants?","Redistributing oil does not remove it from the ecosystem",["They recover every oil molecule in a storage tank","They always restore a food web immediately","They prevent the original spill after it occurs"],"Dispersal changes oil's distribution and exposure pathways. It must not be confused with physical recovery.");
  q("spill-monitor",48,"Which monitoring plan best tests recovery after a spill?","Measure water, sediments, organisms and ecosystem function",["Look once for surface sheen only","Count only the number of cleanup vehicles","Stop as soon as photographs look clean"],"Multiple lines of evidence are needed because contamination and ecological consequences occur in different parts of the system.");
  q("aquifer-safeguard",49,"Which safeguard most directly addresses a well's integrity near aquifers?","Verify casing, cement and separation from groundwater",["Add bird markers to power lines","Replace a turbine tower","Plant grass on a distant mine"],"Match the safeguard to the exposure pathway. Well construction is distinct from surface-storage controls.");
  q("flowback",49,"How should flowback and produced water be managed?","With secure storage, suitable treatment and accountable disposal",["By assuming returned water is clean","By releasing it wherever space is available","By focusing only on the original water withdrawal"],"The water cycle continues after injection. Returned water requires its own handling and disposal safeguards.");
  q("seismic-safeguard",49,"Which response fits the concern about deep wastewater injection and earthquakes?","Assess geology, monitor seismicity and adjust operations",["Ignore local conditions because all wells are identical","Add cooling towers","Measure only the color of surface water"],"Risk management should address the mechanism, local geology and operational evidence.");
  q("prairie-sequence",50,"Which reclamation sequence follows the prairie-restoration example?","Save topsoil, reshape land, replace soil, replant native vegetation",["Replant first, then remove all topsoil","Cover a mine with oil, then add water","Remove drainage and assume recovery is complete"],"Rebuilding soil and vegetation supports recovery, though the original ecosystem may not be completely recreated.");
  q("peatland",51,"A restored site gains tree cover but loses peat wetlands. What is the sound conclusion?","One habitat gain can coexist with loss of other ecosystem functions",["More trees prove every original function returned","Tree area and peatland area measure the same thing","Restoration success needs only one percentage"],"Assess the ecosystem mix and functions. Forest cover alone does not represent peatland recovery.");
  q("overlap",51,"Why should the restoration chart's 'all wetlands' and 'peat wetlands' categories not be added as independent areas?","Peat wetlands are included within all wetlands",["Both percentages must always equal zero","They are energy units","Every wetland is a power plant"],"Overlapping categories double-count some area if summed. Read definitions before calculating totals.");
  q("mountain-restoration",52,"What can a green reclaimed mountaintop mine fail to restore?","Original relief, headwater streams and forest diversity",["Any vegetation of any kind","All possibility of future land use","The fact that gravity exists"],"Revegetation may improve the site without recreating the removed mountain and its ecological relationships.");
  q("backup-power",53,"Which safety improvement directly responds to an extended loss of electric power at a nuclear plant?","Protect backup power and long-duration cooling",["Rely only on the normal power supply","Stop monitoring spent fuel","Replace cooling equipment with a coal-waste pond"],"Safety planning must account for the functions that still matter when normal systems fail.");
  q("combined-hazards",53,"Why plan for simultaneous hazards rather than one failure at a time?","An external event can disable several protective systems together",["Independent backups can never fail","Only one component can fail per day","Cooling matters only during normal operation"],"Common causes can defeat multiple systems. Resilience requires considering combined failures and prolonged disruption.");
  q("passive",54,"Which mechanism illustrates passive cooling?","Gravity-fed water and natural circulation",["Dependence entirely on continuously powered pumps","An unlimited source of cold water with no design limits","Elimination of radioactive decay"],"Natural forces can reduce dependence on active equipment. Passive features still have finite capacities and design requirements.");
  q("passive-limits",54,"What does passive safety NOT establish?","Unlimited cooling under every condition",["Reduced reliance on some powered equipment","Use of natural circulation","Use of gravity to move stored water"],"A passive design still depends on supplies, maintenance and long-term heat removal.");
  q("reprocessing",55,"What is a possible benefit of spent-fuel reprocessing?","Recovering usable nuclear material",["Eliminating every radioactive waste stream","Removing all security concerns","Making uranium renewable on human timescales"],"Recovering uranium and plutonium can extend use of material, but waste and security responsibilities remain.");
  q("fusion-research",55,"How should fusion research be treated in today's energy decisions?","As a potential pathway with major scientific and engineering challenges",["As proof that current waste management can stop","As identical to present commercial fission","As a reason all current plants need no cooling"],"A research pathway does not remove existing safety or waste obligations.");
  q("efficiency-action",58,"Which action can reduce demand while preserving a useful energy service?","Providing the same lighting with a more efficient device",["Leaving an unnecessary light on longer","Counting fuel input as useful output","Ignoring building energy performance"],"Efficiency means providing a service with less input. It complements supply-side and policy decisions.");
  q("central-answer",59,"Which answer best captures the chapter's central synthesis?","Reduce unnecessary demand and manage harms throughout the fuel cycle",["Choose one fuel and assume all remaining impacts disappear","Measure only the electricity price","Wait for future technology before managing existing waste"],"The synthesis combines efficiency, prevention, restoration where possible and long-term care for remaining contamination and waste.");

  group(10, "Science", "Renewable mechanisms");
  q("renewable-meaning",4,"What makes a resource renewable in the course's sense?","It replenishes on timescales relevant to its use",["Its infrastructure has no environmental impact","It produces electricity without a generator","It can never be overused"],"Renewal concerns the resource supply. Infrastructure and operation can still affect ecosystems and communities.");
  q("samso",3,"What is the main lesson of the Samsø example?","A transition combines technologies, heat supply and grid connections",["One device meets every demand at every moment","An energy balance removes the need for imports at every hour","Renewable supply makes demand irrelevant"],"The example describes an energy system. Annual generation and moment-by-moment balancing are different questions.");
  q("solar-origin",4,"Which group consists mainly of pathways ultimately driven by sunlight?","Wind, river flow, waves and biomass",["Geothermal heat and ocean tides","Uranium fission and geothermal heat","Tides and uranium mining"],"Solar heating drives winds and the water cycle; photosynthesis stores solar energy. Geothermal heat and tides have different primary sources.");
  q("tidal-source",14,"What primarily drives ocean tides?","Gravitational interactions",["Local winds alone","Heat from the ocean floor","Evaporation alone"],"Tides follow gravitational cycles. Most surface-wave energy originates with wind.");
  q("wave-source",14,"Where does most ordinary surface-wave energy originate?","Wind transferring energy to water",["The same gravitational cycle that produces tides, without wind","Geothermal heating of deep water","River sediment settling offshore"],"Wind commonly generates surface waves. This distinguishes wave energy from tidal energy.");
  q("solar-paths",5,"Which is a direct use of sunlight without first generating electricity?","Passive solar heating and daylight",["A battery-powered lamp at night","Coal combustion","A nuclear steam turbine"],"Solar energy can provide useful heat or daylight directly. Photovoltaic and concentrating-solar electricity use other pathways.");
  q("pv",6,"What produces electricity in a photovoltaic cell?","Light energizes charge carriers in a semiconductor junction",["Sunlight first heats steam that drives a turbine inside each cell","The panel stores incoming light until it can be burned","The glass cover mechanically rotates a generator"],"The junction helps separate energized charges, allowing current in an external circuit. A PV cell does not need a steam turbine.");
  q("pv-circuit",6,"Why does the photovoltaic illustration include an external circuit?","It provides a path for current through a useful load",["It stores an unlimited amount of light","It turns water into steam in every PV cell","It supplies fossil fuel to the junction"],"Charge separation alone is not the whole useful-energy pathway. A connected load receives electrical energy.");
  q("panel-angle",7,"In the ideal direct-beam example, what happens at 60° from the panel's perpendicular direction?","Intercepted beam power falls to half the perpendicular value",["It becomes twice the perpendicular value","It remains unchanged","It becomes exactly zero"],"The model uses the projected area: cos(60°) = 0.5. It excludes diffuse light, temperature and other real-panel effects.");
  q("angle-reference",7,"In the panel-angle experiment, 0° means what?","The light beam is aligned with the panel's perpendicular direction",["The beam lies parallel to the panel surface","The panel has zero area","The sun has set"],"Angle definitions matter. This model measures the angle from the panel normal, not from the surface.");
  q("csp",8,"How does concentrating solar power differ from photovoltaic conversion?","It concentrates sunlight as heat for a power cycle",["It always converts light directly inside a semiconductor","It requires no heat transfer","It burns sunlight as a chemical fuel"],"CSP uses heat, and the illustrated system drives a steam turbine. PV converts light to electricity directly.");
  q("wind-conversion",9,"Which sequence describes the conventional wind turbine?","Moving air turns a rotor, which drives a generator",["A generator manufactures wind from coal","A rotor stores sunlight chemically","Water boils inside each blade to create lift"],"Aerodynamic forces transfer some air-motion energy to the rotor. A shaft and generator complete the conversion.");
  q("magnus",10,"In the smoke-tunnel demonstration, the spinning cylinder deflects the wake upward. What is the corresponding force on the cylinder?","Downward",["Upward in the same direction as the deflected air","Always zero","Always directly along the incoming flow"],"The cylinder gives the air an upward momentum change; the air exerts a downward force on it in the shown configuration.");
  q("magnus-wind",10,"How should the Magnus demonstration relate to conventional wind turbines?","It illustrates aerodynamic forces but is not the same mechanism as an ordinary blade spinning around the hub",["Every conventional blade spins around its own long axis like the cylinder","It proves turbines need no airflow","It replaces the generator"],"Conventional wind-turbine blades primarily use airfoil lift. A rotating-cylinder Magnus rotor is a distinct device.");
  q("sea-breeze",11,"In the slide's daytime coastal example, near-surface air moves in which direction?","From sea toward land",["Always from land toward sea","Only vertically downward","In no direction because land and water heat identically"],"Different heating rates produce a coastal circulation. The nighttime pattern can reverse.");
  q("hydro",12,"What energy does descending water supply to a hydroelectric turbine?","Energy released as gravitational potential energy decreases",["Chemical energy created in the penstock","Energy from splitting uranium","Electrical energy stored in fish"],"A height difference and water flow enable mechanical power at the turbine, followed by electrical generation.");
  q("head-double",13,"With flow and efficiency unchanged, doubling hydraulic head does what to the classroom model's power?","Doubles it",["Halves it","Quadruples it","Leaves it unchanged"],"The model uses P = ρgQHη. Power is proportional to head H when the other factors stay fixed.");
  q("hydro-units",13,"In the hydropower equation, what does the flow rate Q measure?","Water volume passing per unit time",["Height difference alone","Total water volume in the reservoir","The fraction of input energy converted to electricity"],"Q is a volumetric flow rate, commonly m³/s. It is different from head, which is measured in metres.");
  q("geothermal-source",15,"What is the primary energy source of the geothermal example?","Earth's internal heat",["The daily coastal breeze","Refined petroleum","A photovoltaic junction"],"Geothermal systems transfer internal Earth heat. Their operation depends on resource temperature and local geology.");
  q("binary-fluid",15,"Why does a binary-cycle geothermal plant use a second working fluid?","To receive geothermal heat and vaporize in a separate power cycle",["To mix all geothermal water into drinking water","To produce coal from steam","To eliminate the need for a generator"],"Heat passes between separate circuits. The working fluid drives a turbine while geothermal water can return underground.");
  q("biomass-energy",16,"Where is the energy of wood or other biomass stored before use?","In chemical bonds",["Only in the speed of the wind","In a permanent electrical current","In newly created uranium"],"Biomass stores chemical energy that can be released by combustion or converted into fuel.");
  q("biofuel-pairs",16,"Which pairing matches the presentation?","Sugars and starches can yield ethanol; oils and fats can yield biodiesel",["Uranium yields ethanol; sand yields biodiesel","Wind yields ethanol; tides yield coal","All feedstocks require no processing"],"Different feedstocks and conversion processes produce different fuels, each with its own resource requirements.");
  q("cellulose",17,"Why is cellulosic ethanol processing more involved than simply fermenting accessible sugars?","Cellulose must first be broken down to accessible sugars",["Cellulose is a radioactive isotope","Microbes turn intact steel directly into ethanol","Fermentation is unnecessary in every pathway"],"Pretreatment and enzymes help release sugars, which microbes can then ferment.");
  q("ferment",17,"What is the role of microbes in the illustrated ethanol pathway?","Fermenting accessible sugars",["Turning a generator shaft","Producing sunlight","Separating crude oil by boiling point"],"The sequence distinguishes making sugars accessible from fermenting them and recovering ethanol.");
  q("turbine-quiz",18,"Which electricity pathway does not require a turbine in the slide's examples?","Photovoltaic solar",["Concentrating solar with a steam cycle","Hydroelectric generation","Wind generation"],"PV uses a semiconductor. The other listed examples convert mechanical rotation through a generator.");

  group(10, "Issues", "Ecosystems and communities");
  q("renewable-impact",20,"A project uses a renewable resource. What follows about its environmental footprint?","Its land, water and community impacts still need assessment",["It cannot damage habitat","It never requires materials","It has no downstream consequences"],"Resource renewal does not guarantee zero impact. Technology, location, scale and operating practices determine many effects.");
  q("solar-habitat",21,"How can roads at a solar development affect wildlife even outside panel footprints?","They can fragment habitat and interrupt movement",["They eliminate every habitat barrier","They create more sunlight","They guarantee all species benefit"],"Infrastructure divides or alters habitat as well as occupying land directly.");
  q("csp-water",22,"Why can wet-cooled concentrating solar power be challenging in dry regions?","Steam-cycle cooling can compete for scarce water",["All solar panels must burn coal","Sunlight cannot reach dry places","Cooling water is created without any input"],"A strong solar resource can coincide with limited water. Cooling design is therefore important.");
  q("pv-csp-water",22,"Can the water requirement of one thermal solar plant be assigned automatically to every PV installation?","No; their mechanisms and cooling needs differ",["Yes; every solar device is an identical steam plant","Yes; all use the same reservoir","No; therefore PV has no lifecycle water use"],"Distinguish technology-specific operation from life-cycle resource use. Avoid treating all solar systems as identical.");
  q("eroei5",23,"A system delivers 200 energy units and requires 40 units to obtain them. What is its EROEI?","5",["160","0.2","240"],"EROEI = delivered energy / energy invested = 200 / 40 = 5, using the stated accounting boundary.");
  q("net160",23,"For 200 energy units delivered with 40 invested, what is net energy?","160 units",["5 units","240 units","40 units"],"Net energy = 200 − 40 = 160 units. This is a difference, whereas EROEI is a ratio.");
  q("eroei-limits",23,"What does an EROEI value alone fail to describe?","The complete environmental and social consequences",["The energy-output to energy-investment ratio","The quantities used in its calculation","A specified energy-accounting comparison"],"EROEI is an energy metric. Habitat, water, distribution of benefits and other impacts require additional evidence.");
  q("bird-bat",24,"Why should wildlife risk at wind farms be evaluated by site and season?","Species, migration routes and operating conditions vary",["Every turbine kills exactly the same number of animals","Wildlife never moves between habitats","Season has no connection to exposure"],"Exposure and vulnerability differ. The presentation emphasizes siting, species and operation.");
  q("transmission",25,"Why include power lines and access roads in a wind-project assessment?","They extend the project's ecological footprint beyond the turbines",["They have no relationship to electricity delivery","Only the rotor can ever affect habitat","They are automatically underground"],"Connections that deliver electricity can cause collisions, disturbance and habitat fragmentation.");
  q("dam-sediment",26,"What can a reservoir do to sediment moving through a river?","Trap sediment and change downstream supply",["Guarantee unchanged sediment transport","Convert all sediment into electricity","Remove the need for downstream monitoring"],"Dams change more than water level. Sediment retention can alter habitats and river processes downstream.");
  q("fish-barrier",26,"Why can a dam affect fish populations?","It can obstruct migration and alter habitat conditions",["Fish receive electricity directly from the reservoir","All fish prefer any new barrier","A dam guarantees identical water temperature"],"Migration barriers and changes in flow, temperature or oxygen can matter together.");
  q("reservoir-ghg",26,"Why can a reservoir have greenhouse-gas emissions despite not burning fossil fuel at its turbine?","Flooded organic matter can decompose and release gases",["A turbine creates coal","Water is always a fossil fuel","All reservoirs have exactly the same emissions"],"The full pathway includes flooded ecosystems and site conditions. Hydropower emissions cannot be inferred from combustion alone.");
  q("displacement",27,"What does 'displacement of communities and loss of livelihoods' mean in the dam example?","People may lose homes, work and access to resources when land floods",["Only water molecules move","Everyone automatically receives equivalent land and income","Electricity users always live beside the reservoir"],"Flooding can affect housing, farming, fishing and cultural places. Benefits and burdens may reach different people.");
  q("fairness",27,"Which question most directly examines fairness in a hydropower project?","Who receives the electricity, and who bears relocation and livelihood costs?",["How much electricity will the project generate in total?","What is the average turbine efficiency?","How high is the dam wall?"],"A distributional assessment asks who benefits and who experiences harm, not just whether total electricity increases.");
  q("food-competition",28,"How can expansion of crop-based biofuels affect food systems?","It can compete for agricultural land, water and crops",["It makes agricultural land unlimited","It eliminates fertilizer runoff","It guarantees lower food demand"],"Fuel production can interact with food production and land-use change. The feedstock and production system matter.");
  q("runoff",28,"Which pathway links intensive biofuel agriculture to water impacts?","Fertilizer runoff from fields",["A photovoltaic junction separating charges","A turbine absorbing neutrons","A condenser creating soil"],"Upstream agricultural inputs and runoff belong in the fuel's assessment, even when combustion occurs elsewhere.");
  q("biofuel-boundary",29,"Which comparison is most informative for two biofuel options?","Their full feedstock-to-fuel pathways under consistent boundaries",["Only whether both carry a renewable label","Only the color of the liquid","Only the final combustion device"],"Land conversion, water, soil and processing can change the comparison. A label alone is insufficient.");
  q("solar-site-choice",29,"Two solar proposals have the same rated power. What else is needed to compare their impacts?","Site conditions, habitat effects and technology-specific resource needs",["Nothing; rated power fixes every impact","Only which one has more panels, regardless of site","Only construction cost, excluding environmental conditions"],"Rated power describes a generation capability, not a complete environmental assessment.");
  q("low-carbon-renewable",20,"Which statement best separates renewable supply from low-impact development?","A renewable source can still require harmful land conversion",["Renewable means zero habitat loss by definition","Renewable means no materials are needed","Renewable means no operating constraints"],"Resource renewal and environmental performance are different properties that must be considered together.");
  q("multiple-effects",30,"Which plan best follows the Issues summary?","Assess solar habitat/water, wind wildlife, river change and biofuel land use",["Use one environmental metric for every technology without context","Assess only the power plant fence line","Ignore people because the course is about nature"],"The summary identifies distinct mechanisms. Comparisons should follow the relevant pressures and affected communities.");

  group(10, "Solutions", "Design and reliability");
  q("rooftops",31,"Why consider suitable rooftops and developed sites for solar?","They can reduce pressure to clear intact habitat",["They guarantee every roof is structurally suitable","They eliminate shading and grid constraints","They make manufacturing impacts disappear"],"Developed sites can reduce some land impacts, but structural, shading and connection checks remain necessary.");
  q("thermal-store",32,"What does molten-salt storage primarily store?","Thermal energy",["Free electrons without a circuit","Unburned coal","Wind speed"],"Thermal storage retains heat for later use. Useful temperature and heat loss matter.");
  q("pumped-store",32,"Pumped storage stores energy mainly by doing what?","Raising water to a higher elevation",["Manufacturing new water","Separating uranium isotopes","Creating a stronger sun"],"The stored gravitational potential energy can later drive a turbine. Pumping and generation have losses.");
  q("battery-units",32,"Why are both MW and MWh needed to describe a battery?","MW limits its delivery rate; MWh limits total usable energy",["They are two spellings of the same quantity","MW gives its mass; MWh gives its temperature","MWh alone specifies its maximum power"],"A storage system can have enough energy but insufficient power, or enough power for only a short duration.");
  q("storage80",33,"With 2.0 MWh charged and 80% round-trip efficiency, how much energy can the model return?","1.6 MWh",["2.5 MWh","2.0 MWh","0.4 MW"],"Delivered energy = 2.0 × 0.80 = 1.6 MWh. These are classroom assumptions.");
  q("storage-shortfall",33,"The evening needs 2.0 MWh but storage delivers 1.6 MWh. What remains to be supplied or avoided?","0.4 MWh",["0 MWh","3.6 MWh","0.4 MW regardless of duration"],"The energy shortfall is 2.0 − 1.6 = 0.4 MWh. A power shortfall would also need a time interval.");
  q("repower",34,"What is the appropriate claim about replacing old wind-turbine designs?","It can reduce some risks, but siting and monitoring still matter",["It eliminates all bird and bat mortality everywhere","It removes the need for transmission lines","It guarantees identical outcomes at every site"],"Design is one part of mitigation. Local exposure and operating practices also matter.");
  q("bat-curtail",35,"Which intervention is illustrated for reducing bat fatalities?","Reduce rotor motion during high-risk low-wind periods",["Make all blades invisible to radar","Ignore seasonal activity","Operate every turbine identically regardless of conditions"],"The study example tests changed operation during a particular risk period. Results support targeted mitigation, not a zero-risk promise.");
  q("study-generalize",35,"How should the bat-study result from one Alberta site be applied elsewhere?","As evidence to inform local testing and monitoring",["As a guaranteed identical reduction at every wind farm","As proof bats are unaffected by turbines","As a substitute for measuring outcomes"],"Species, weather, season and turbine operation differ. Site-specific evidence matters.");
  q("line-markers",36,"What is the intended function of markers on high-risk power-line spans?","Make the lines more visible to birds",["Prevent every kind of electrical injury without changing line design","Eliminate the need for careful routing","Prove collision risk is zero without monitoring"],"Markers address collision visibility. Routing and monitoring remain important.");
  q("transmission-route",36,"Which route choice can reduce new habitat disturbance?","Use suitable existing rights of way while checking wildlife risks",["Build through important roosting areas by default","Choose solely by shortest distance without assessment","Assume all existing routes are automatically safe"],"Existing corridors can reduce some additional disturbance, but suitability must still be assessed.");
  q("run-of-river",37,"What is a key safeguard in the run-of-the-river example?","Maintain ecological flow in the main channel",["Divert all river water whenever possible","Treat fish passage as irrelevant","Assume little storage means zero impact"],"The example combines limited diversion, ecological flow and fish passage. A smaller reservoir does not eliminate ecological duties.");
  q("existing-dams",38,"Why assess suitable existing unpowered dams before adding a new barrier?","Some generation may be possible with less new fragmentation",["Every existing dam should automatically remain forever","Every existing dam can safely generate equal power","No environmental assessment is needed"],"Compare refurbishment with removal and alternatives. Existing infrastructure offers options, not universal answers.");
  q("fish-passage",38,"A fish bypass is installed. What is the best next step?","Monitor whether relevant species can actually pass",["Assume all river functions have returned","Stop measuring ecological flow","Remove all upstream habitat"],"A structure's presence does not establish its ecological effectiveness. Outcomes need verification.");
  q("residues",39,"Why can suitable residues or wastes be preferable biofuel feedstocks?","They may reduce pressure to grow dedicated fuel crops",["They always have zero collection and processing costs","Removing residues can never affect soils","They require no life-cycle assessment"],"Residues can avoid some land competition, but soil needs, transport and processing still matter.");
  q("algae",39,"How should algae-based fuels be evaluated?","Over the full life cycle, including cultivation and processing inputs",["As automatically impact-free because algae grow","Only by the appearance of a pond","Without considering energy or water inputs"],"A promising feedstock still requires water, nutrients, energy and conversion. Compare complete systems.");
  q("policy",40,"Which policy package follows the presentation?","Clear permitting, environmental safeguards and meaningful community participation",["Fast construction with no community voice","Subsidies with no environmental conditions or evaluation","Only a new project slogan"],"Technical design and social decisions jointly shape outcomes. Enforceable safeguards and fair participation matter.");
  q("community-voice",40,"What does meaningful community participation require?","A real opportunity to influence decisions and distribution of benefits",["Only being informed after construction is complete","Assuming every household experiences the same impact","Replacing evidence with a single publicity event"],"Participation concerns how decisions are made and whose interests and knowledge shape them.");
  q("grid-gap",42,"After sunset: demand is 10 MW, wind supplies 3 MW and hydro 4 MW. What is the remaining power gap?","3 MW",["7 MW","12 MWh","0 MW"],"10 − 3 − 4 = 3 MW. Direct PV output is assumed zero in this classroom scenario.");
  q("grid-four-hours",42,"A constant 3 MW gap lasts four hours. How much usable storage energy is required?","12 MWh",["3 MWh","0.75 MWh","12 MW"],"Energy = power × time = 3 MW × 4 h = 12 MWh.");
  q("battery-exact",42,"A full battery has 12 MWh usable output and a 3 MW discharge limit. Can it fill the 3 MW gap for four hours?","Yes, exactly under the stated assumptions",["No, because MW and MWh must have equal numbers","Yes, with unlimited energy left","No, because batteries can never supply power at night"],"Both constraints are met exactly: power is 3 MW and required energy is 12 MWh. No additional losses are deducted from capacity already specified as usable output.");
  q("wind-drop",43,"Wind falls to 1 MW while demand is 10 MW and hydro supplies 4 MW. What is the new gap?","5 MW",["3 MW","1 MW","20 MW"],"10 − 1 − 4 = 5 MW. The same 3 MW battery is now power-limited as well as short of energy over four hours.");
  q("wind-response",43,"In that four-hour low-wind scenario, what change makes the original 3 MW / 12 MWh battery sufficient?","Reduce demand by 2 MW for the whole period",["Reduce demand for one second only","Increase battery energy while ignoring its 3 MW limit","Count midnight PV as guaranteed generation"],"Demand becomes 8 MW. Wind plus hydro supplies 5 MW, leaving 3 MW for four hours, or 12 MWh.");
  q("zero-impact",45,"Which answer best reflects the chapter's central question?","Renewables can reduce harms, but zero impact is not a realistic promise",["Any renewable project has zero impact","Only power output matters","All renewable technologies have identical consequences"],"Lower demand, careful siting, suitable design and verified safeguards improve outcomes. Context still matters.");
  q("personal-system",46,"How do individual efficiency choices relate to institutional action?","They complement changes by industry, institutions and government",["They replace every need for environmental regulation","They make supply planning irrelevant","They cannot affect any energy use"],"The presentation links personal choices with collective decisions rather than treating either as the whole solution.");

  // Visual questions use original schematic models or existing attributed course figures.
  // The descriptions and numerical settings remain available when motion is paused.
  group(9, "Science", "Visual energy lab");
  q("visual-heat",28,"Run the heat-balance model. At 40% efficiency with 100 input units, how much energy leaves as heat?","60 units",["40 units","100 units","140 units"],"Input = electricity + rejected heat. Here 100 = 40 + 60. This simplified teaching balance is not a measurement of a particular plant.",{kind:"heat",setting:40});
  q("visual-input",28,"Set the heat model to 25% efficiency. Which output pair conserves its 100 input units?","25 electricity and 75 heat",["25 electricity and 100 heat","75 electricity and 25 heat","25 electricity and 25 heat"],"At 25% efficiency the useful fraction is 25 units. Conservation leaves 75 units as heat.",{kind:"heat",setting:25});
  q("visual-generator",5,"Inspect the generator figure. What supplies its mechanical input in a steam plant?","A rotating turbine shaft",["The transmission line consuming power","Fresh fuel entering the condenser","The light emitted by a bulb"],"The turbine and generator are different devices: one produces shaft rotation and the other converts it into electricity.",{kind:"figure",asset:"generator",alt:"Reconstructed generator with rotating shaft, magnetic field and electrical output."});
  q("visual-fossil",3,"Follow the illustrated fossil-power system. Which component supplies heat to the working water?","The fuel-burning boiler",["The electrical transmission line","The condenser alone","The outlet socket"],"Combustion heats water to produce steam. The turbine, generator and condenser have different roles.",{kind:"figure",asset:"fossil-power",alt:"Fuel burns in a boiler; steam reaches a turbine and generator; a cooling system returns water."});
  q("visual-nuclear",21,"Compare the nuclear-power figure with a fossil steam plant. Which part of the energy sequence changes most fundamentally?","The process supplying the heat",["The requirement to conserve energy","The meaning of electricity","The fact that a generator converts rotation"],"Fission replaces combustion as the heat source. Both illustrated plants still transfer heat and use a turbine-generator.",{kind:"figure",asset:"nuclear-power",alt:"Nuclear reactor transfers heat through separate circuits to steam, turbine, generator and cooling system."});
  group(9, "Issues", "Visual fieldwork");
  q("visual-mine",35,"Inspect the mining photograph. Which follow-up measurement best tests a downstream water concern?","Stream chemistry and flow above and below the disturbed area",["Only the number of buildings in a distant city","The color of a turbine rotor","The voltage of an unrelated solar panel"],"A photograph can identify disturbance, but testing water impacts requires relevant measurements and comparison locations.",{kind:"figure",asset:"mountaintop-mining",alt:"A mountaintop mining site with exposed rock, altered ridges and remaining forest."});
  q("visual-spill",38,"The photograph shows wildlife response after a spill. What additional evidence is needed to judge ecosystem recovery?","Conditions in habitats, water, sediment and populations over time",["Only whether one rescued bird looks clean","Only the number of photographs taken","Only the color of the cleanup vehicle"],"Animal rescue is important but does not by itself measure recovery of the wider ecosystem.",{kind:"figure",asset:"oil-spill-response",alt:"Responders handle an oiled bird during an oil-spill wildlife response."});
  group(9, "Solutions", "Response-room decisions");
  q("visual-boom",48,"In the response-room schematic, oil is moving toward a wetland. Which action addresses spread before it reaches the habitat?","Deploy suitable containment booms where conditions allow",["Wait until every organism is visibly oiled","Call surface dispersal complete removal","Ignore current direction"],"Containment can protect sensitive areas, but feasibility depends on currents, waves and the oil. The schematic is not a field response plan.",{kind:"spill"});
  q("visual-spill-followup",48,"Pause the moving slick. If the surface later looks clear, which statement is justified?","Recovery still needs ecological and chemical monitoring",["All oil must have vanished","All habitats have returned to baseline","Monitoring would be redundant"],"Visible surface condition is only one indicator. Oil and consequences can persist elsewhere in the system.",{kind:"spill"});
  q("visual-pathway",44,"The pathway diagram continues beyond electricity generation. Why?","Waste and long-term management remain part of the system",["A power plant creates no useful output","All waste is automatically recycled","Extraction happens only after disposal"],"Follow the full chain from resource extraction through use and continuing waste responsibilities.",{kind:"pathway"});

  group(10, "Science", "Visual renewable lab");
  q("visual-panel",7,"Move the panel-angle slider to 60°. What fraction of the perpendicular direct-beam power remains in this ideal model?","One half",["One quarter","Twice as much","None"],"Projected interception scales with cos(θ), so cos(60°) = 0.5. This is an ideal geometry model, not measured panel performance.",{kind:"solar",setting:60});
  q("visual-head",13,"Set the water drop to 20 m. With Q = 1 m³/s and efficiency = 80%, what approximate power does the model give?","157 kW",["16 kW","1,570 kW","20 MWh"],"P = 1,000 × 9.81 × 1 × 20 × 0.80 W = 156,960 W, or about 157 kW.",{kind:"hydro",setting:20});
  q("visual-head-ratio",13,"Compare 10 m and 30 m in the hydropower model. How does power change with flow and efficiency held constant?","It triples",["It increases ninefold","It stays the same","It falls to one third"],"Power is proportional to head in this model. Tripling H triples P when Q and efficiency do not change.",{kind:"hydro",setting:10});
  q("visual-pv",6,"Look at the photovoltaic mechanism. Which step is absent from this direct conversion?","Steam turning a turbine",["Light supplying energy","Charge separation at a junction","Current flowing through an external circuit"],"The PV pathway is direct light-to-electricity conversion in a semiconductor.",{kind:"figure",asset:"photovoltaic",alt:"Light reaches a photovoltaic junction, charges separate and current powers an external circuit."});
  q("visual-geothermal",15,"In the binary geothermal figure, why reinject the cooled geothermal water?","It returns the extracted fluid underground as part of the resource-management cycle",["It creates an unlimited heat supply","It converts all water into petroleum","It eliminates the need to assess local geology"],"Reinjection is part of managing the fluid and resource. Sustainable operation still depends on local conditions and extraction rates.",{kind:"figure",asset:"geothermal",alt:"Hot geothermal fluid transfers heat to a separate working fluid and returns underground through an injection well."});
  group(10, "Solutions", "Grid-control challenges");
  q("visual-storage",33,"Set round-trip efficiency to 80%. Of 2 MWh charged, what does the model deliver?","1.6 MWh",["2.0 MWh","2.8 MWh","0.8 MW"],"The output is 2 × 0.80 = 1.6 MWh. Storage shifts energy in time and incurs losses.",{kind:"storage",setting:80});
  q("visual-grid",42,"Set wind to 3 MW in the four-hour grid model. Can the full 3 MW / 12 MWh battery cover the gap?","Yes, exactly in this model",["No, its energy is insufficient","No, its power limit is exceeded","Yes, with half its energy unused"],"Demand 10 − wind 3 − hydro 4 = 3 MW. Four hours requires 12 MWh usable output.",{kind:"grid",setting:3});
  q("visual-grid-low",43,"Set wind to 1 MW. Which two battery constraints are now exceeded?","The 3 MW power limit and the 12 MWh energy capacity",["Neither constraint","Only the energy capacity","Only the power limit"],"The gap is 5 MW for four hours, requiring 20 MWh. Both are greater than this battery's stated capabilities.",{kind:"grid",setting:1});
  q("visual-grid-demand",43,"At 1 MW wind, lower demand from 10 MW to 8 MW. What changes?","The gap becomes 3 MW and 12 MWh over four hours",["The battery generates new energy","Hydro automatically doubles","The gap becomes zero"],"With hydro fixed at 4 MW, the gap is 8 − 1 − 4 = 3 MW, matching the battery's power and usable energy limits.",{kind:"grid",setting:1});
  group(10, "Issues", "Visual fieldwork");
  q("visual-reservoir",27,"The reservoir-community photograph points to which question that a generation-only assessment might miss?","What happens to residents' homes, livelihoods and cultural places?",["What is the rated electrical capacity?","How many turbines will generate electricity?","What is the generator's conversion efficiency?"],"Energy benefits and displacement costs may reach different people. Meaningful participation and livelihood assessment belong in the decision.",{kind:"figure",asset:"reservoir-community",alt:"A resident and a partly demolished home in an area affected by reservoir development."});

  const chapters = {
    9: { title: "Fossil Fuels and Nuclear Energy", deck: "Chapter_9.pptx", href: "../lectures/guest-lecture-01-energy-systems/" },
    10: { title: "Renewable Energy", deck: "Chapter_10.pptx", href: "../lectures/guest-lecture-02-renewable-transition/" }
  };
  window.ENV_SCIENCE_BANK = Object.freeze({ version: "2026-10-20", chapters, questions });
}());
